inputs = ['fb', 'hgbgi', 'iadz', 'faz', 'uev']
outputs = ['yfab', 'hgbgi', 'iadz', 'abz', 'uev']

# Let me see what exactly changes in each pair
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find positions where they differ
        for j, (c1, c2) in enumerate(zip(inp, outp)):
            if c1 != c2:
                print(f"  Position {j}: '{c1}' -> '{c2}'")
        # Also check lengths
        if len(inp) != len(outp):
            print(f"  Length changed: {len(inp)} -> {len(outp)}")
    else:
        print("  No change")

